function countyRoom(kind){if(kind==='countyCamp'){countyCampMenu();return}if(kind==='legacyRoom'){countyLegacy();return}if(kind==='midnightMarket'||kind==='moonGarden'){countyHiddenMenu(kind);return}if(kind==='countyBakery'){if(!state.cityCounty.stories.fernBakery?.complete){countyResident('fernBakery');return}modal('Fern’s Hearth Bakery · OPEN','<p class="life-dialogue">“You helped turn the lights on again. There is a place for you beside this oven.”</p>');action('Bake another warm batch',()=>lifePuzzle('county_loaf','Fern’s reopened bakery',a=>{if(!county.check(state,'loaf',a))return{ok:false,reason:county.puzzles.loaf.hint};const c=atmosphere.conditions(state),q=county.ensure(state),key='bakery:'+c.key;if(q.celebrated[key])return{ok:true,title:'A warm practice batch, shared with the neighborhood'};q.celebrated[key]=true;state.cookedMeals=(state.cookedMeals||0)+1;state.life??={};state.life.bag??={};state.life.bag['woodland loaf']=(state.life.bag['woodland loaf']||0)+1;county.event(state,key,'Fresh bread at Fern’s reopened bakery','The first batch of the day has brought another warm welcome.','resident',c);return{ok:true,title:'A fresh woodland loaf is yours'}}));action('Read Fern’s letter',()=>countyLetters());}}
function countyHub(tab='paper'){modal('Life in Eldoria County','<p>A county that remembers your kindness, welcomes your camping adventures, and wakes to what midnight changed.</p><div id="countyTabs" class="life-tabs"></div><div id="countyContent"></div>');for(const [id,title]of [['paper','The Eldoria Lantern'],['people','Residents’ stories'],['season','Seasonal gatherings'],['morning','Morning & letters'],['places','Places & camping']]){const b=document.createElement('button');b.textContent=title;b.setAttribute('aria-pressed',String(id===tab));b.onclick=()=>countyHub(id);$('countyTabs').append(b)}const area=$('countyContent'),c=atmosphere.conditions(state),q=county.ensure(state);function card(title,text,label,fn){const a=document.createElement('article');a.className='life-board-card';a.innerHTML='<h3>'+lifeEsc(title)+'</h3><p>'+lifeEsc(text)+'</p>';const b=document.createElement('button');b.textContent=label;b.onclick=fn;a.append(b);area.append(a)}
if(tab==='paper'){area.innerHTML='<article class="county-paper"><div class="county-paper-kicker">THE COUNTY’S STORIES, KEPT WITH CARE</div><h1>The Eldoria Lantern</h1><p class="county-paper-date">'+lifeEsc(atFormat(new Date(),{weekday:'long',year:'numeric',month:'long',day:'numeric'}))+' · '+atCap(c.season)+' edition</p><h2>Embermere welcomes campers to the bonfire circle</h2><p>Pitch a tent, cook a woodland supper, and share stories beside the lake. Saturday bonfire gatherings welcome old neighbors and new arrivals.</p><h3>In season: '+lifeEsc(county.seasons[c.season].title)+'</h3><p>'+lifeEsc(county.seasons[c.season].text)+'</p>'+q.events.slice(0,12).map(e=>'<section><small>'+lifeEsc(e.day)+' · '+lifeEsc(e.kind)+'</small><h2>'+lifeEsc(e.title)+'</h2><p>'+lifeEsc(e.text)+'</p></section>').join('')+(!q.events.length?'<p>Your first adventures will become the county’s next headlines.</p>':'')+'</article>';card('Your next gathering',county.seasons[c.season].title,'Join the seasonal celebration',countySeason);}
if(tab==='people')county.stories.forEach(st=>{const i=county.storyInfo(state,st.id);card((i.progress.complete?'✓ ':'')+st.title,st.person+' · '+(i.progress.complete?st.outcome:i.step.text),i.progress.complete?'Read the thank-you letter':'Follow this resident’s story',()=>i.progress.complete?countyLetters():countyResident(st.id))});
if(tab==='season'){for(const [season,a]of Object.entries(county.seasons))card(atCap(season)+' · '+a.title,a.text+(season===c.season?' · Happening this season.':' · Returns with its season.'),season===c.season?'Join this gathering':'Read about the gathering',()=>{if(season===c.season)countySeason();else{modal(a.title,'<p>'+lifeEsc(a.text)+'</p><p>This gathering follows your selected world season. Your calendar and Weather & seasons controls show the current season.</p>');action('Weather & seasons',atSettings)}})}
if(tab==='morning'){const mornings=q.events.filter(e=>e.kind==='morning');for(const e of mornings.slice(0,8))card(e.title,e.text,q.reactions[e.key]?'A moment already shared':'Answer this neighbor',()=>{const r=county.respond(state,e.key,c);if(!r.ok){cityMessage(r.reason);return}lifeCommit();modal(r.title,'<p>Your neighbor remembers the kindness. Your friendship has grown.</p>');action('Read the county letters',countyLetters)});if(!mornings.length)area.innerHTML='<p>After your next midnight creations, return after 6 a.m. to hear what the neighbors remembered. Letters and reactions stay here.</p>';card('Letters for your legacy room',q.letters.length+' letters received.','Open my letters',countyLetters);}
if(tab==='places'){for(const [kind,r]of Object.entries(countyRooms))card(r.title,r.text,'Visit '+r.title,()=>countyVisit(kind,()=>countyRoom(kind)));}action('Go to my bonfire camp',countyVisitCamp);action('Visit my legacy room',()=>countyVisit('legacyRoom',countyLegacy));action('Return to Eldoria',()=>{$('modal').close();cityDraw()})}
function countyLetters(){const q=county.ensure(state);modal('Letters from your county',q.letters.map(l=>'<article class="county-letter"><small>'+lifeEsc(l.day)+' · '+lifeEsc(l.person)+'</small><h3>'+lifeEsc(l.title)+'</h3><p class="life-dialogue">'+lifeEsc(l.text)+'</p></article>').join('')||'<p>Your first letters will arrive as the county remembers your adventures.</p>');action('Display a letter at home',()=>countyVisit('legacyRoom',countyLegacy));action('Read The Eldoria Lantern',()=>countyHub('paper'))}
function countyResident(id){const i=county.storyInfo(state,id);if(!i||i.progress.complete){countyLetters();return}if(!county.at(i.step,lifeWhere())){heritageTravel(i.step.district,i.step.room,()=>countyResident(id));return}lifePuzzle('county_'+i.step.puzzle,i.story.title+' · '+(i.progress.step+1)+'/3 · '+i.step.text,a=>county.answerStory(state,id,a,lifeWhere(),atmosphere.conditions(state)),()=>{const next=county.storyInfo(state,id);modal('A resident’s story continues','<p>'+lifeEsc(next.step.text)+'</p>');action('Continue this resident’s story',()=>countyResident(id));action('Pause and explore',()=>{$('modal').close();cityDraw()})})}
function countySeason(){const c=atmosphere.conditions(state),a=county.seasons[c.season];if(!county.at(a,lifeWhere())){heritageTravel(a.district,a.room,countySeason);return}lifePuzzle('county_'+a.puzzle,a.title,response=>county.celebrate(state,response,lifeWhere(),atmosphere.conditions(state)))}
function countyCampMenu(){if(cityInside!=='countyCamp'){countyVisitCamp();return}const c=atmosphere.conditions(state),q=county.ensure(state),day=q.campDays[c.key]||{};modal('Embermere · bonfires, tents & belonging','<p class="life-dialogue">Lanterns sway above the log benches. The lake reflects the fire, and the woodland leaves room for one more camper.</p><p>Your tent: <strong>'+(q.tent?'pitched and waiting':'ready to pitch')+'</strong> · Today’s fire: <strong>'+(day.fire?'warm and glowing':'ready for your care')+'</strong></p><p>Every Saturday is a county bonfire gathering. You can camp, cook and share stories here any day.</p>');lifePhoto('countyCamp');if(q.stories.aureliaSong?.complete)$('modal').insertAdjacentHTML('beforeend','<p>Aurelia’s recovered melody is now part of the bonfire’s music.</p>');if(q.stories.pipGathering?.complete)$('modal').insertAdjacentHTML('beforeend','<p>Pip’s family remembers your welcome. There is a quiet corner beside the singing circle.</p>');county.campActivities.forEach(a=>action(a.title,()=>countyCampActivity(a.id)));action('Share or enjoy my campfire food',countyCampFood);action('Choose a tale for the bonfire',countyTales);action('Settle into my tent for the night',()=>{const r=county.settle(state,lifeWhere(),atmosphere.conditions(state));if(!r.ok){modal('Your overnight camp','<p>'+lifeEsc(r.reason)+'</p>');action('Pitch my canvas tent',()=>countyCampActivity('tent'));return}lifeCommit();modal(r.title,'<p>Your overnight stay is saved. The real clock keeps moving; when you return after dawn, the county will remember your camping morning.</p>');action('Rest here beside the bonfire',()=>{$('modal').close();cityDraw()})});action('Save a campground photograph',()=>{county.photo(state,'embermere','My camp beside the Embermere bonfire','county-camp',atmosphere.conditions(state));lifeCommit();modal('A camping photograph saved','<p>Your photograph is ready to frame in your legacy room.</p>');action('Visit my legacy room',()=>countyVisit('legacyRoom',countyLegacy))});action('Join the current seasonal gathering',countySeason);action('Enjoy the clearing',()=>{$('modal').close();cityDraw()})}
function countyCampActivity(id){if(cityInside!=='countyCamp'){countyVisit('countyCamp',()=>countyCampActivity(id));return}const a=county.campActivities.find(a=>a.id===id);lifePuzzle('county_'+a.puzzle,a.title,response=>county.camp(state,id,response,lifeWhere(),atmosphere.conditions(state)))}
function countyCampFood(){const bag=state.life?.bag||{},foods=['woodland stew','golden toasted treat','woodland breakfast','woodland loaf'].filter(food=>bag[food]>0);modal('Supper beside your bonfire','<p>Enjoy what you cooked or share it with the circle. Each serving comes from your saved camping food.</p>');if(!foods.length)$('modal').insertAdjacentHTML('beforeend','<p>Cook woodland stew, toast a treat, or return after an overnight camp for breakfast.</p>');for(const food of foods)for(const share of [false,true])action((share?'Share ':'Enjoy ')+food+' · '+bag[food]+' serving(s)',()=>{const r=county.eat(state,food,share,lifeWhere(),atmosphere.conditions(state));if(!r.ok)return;lifeCommit();modal(r.title,'<p>'+ (share?'Warm food and a little kindness make the circle feel like home.':'You settle in with a warm plate beside the fire.')+'</p>');action('Back to the campground',countyCampMenu)});action('Cook a woodland supper',()=>countyCampActivity('stew'))}
