function countyHiddenMenu(kind){if(!promise.active(state)){countyVisit(kind);return}modal(cityRoomNames[kind],'<p>'+lifeEsc(countyRooms[kind].text)+'</p><p>This path stays open through the Midnight Promise. Your keepsakes remain yours after the door closes.</p>');const id=kind==='midnightMarket'?'market':'garden',puzzle=id==='market'?'trade':'moonflower';action('Discover tonight’s hidden keepsake',()=>lifePuzzle('county_'+puzzle,cityRoomNames[kind],answer=>county.hidden(state,id,answer,lifeWhere(),atmosphere.conditions(state))));action('Save a photograph of this hidden place',()=>{if(!promise.active(state)||cityInside!==kind){countyVisit(kind);return}county.photo(state,kind,cityRoomNames[kind],kind==='midnightMarket'?'county-market':'county-garden',atmosphere.conditions(state));lifeCommit();modal('A midnight photograph saved','<p>The hidden place will stay in your legacy room after dawn.</p>')});action('Stay a little longer',()=>{$('modal').close();cityDraw()})}
function countyLegacy(){if(cityInside!=='legacyRoom'){countyVisit('legacyRoom',countyLegacy);return}const q=county.ensure(state),items=county.legacyItems(state);modal('Your legacy, furnished with memories','<p>Choose up to eight letters, photographs, creations and keepsakes to display in this room. Their stories remain available whenever you visit.</p><p id="countyLegacyFeedback" role="status"></p><div id="countyLegacyItems" class="county-legacy-list"></div>');for(const item of items){const card=document.createElement('article');card.className='life-board-card';card.innerHTML='<small>'+lifeEsc(item.type)+'</small><h3>'+lifeEsc(item.title)+'</h3>';const b=document.createElement('button');b.textContent=q.displays[item.id]?'Put this memory away':'Display this memory';b.dataset.memory=item.id;b.onclick=()=>{const r=county.display(state,item.id);if(!r.ok){$('countyLegacyFeedback').textContent=r.reason;return}lifeCommit();countyLegacy()};card.append(b);$('countyLegacyItems').append(card)}if(!items.length)$('countyLegacyItems').innerHTML='<p>Your shelves are ready. Make a midnight creation, help a resident, or take your first camping photograph.</p>';action('See my furnished legacy room',()=>{$('modal').close();cityDraw();$('cityScene').scrollIntoView({block:'start'})});action('Visit my campground',countyVisitCamp)}
function countyRenderLegacy(){let wall=$('countyLegacyWall');if(!wall){wall=document.createElement('div');wall.id='countyLegacyWall';$('citySceneWorld').append(wall)}wall.replaceChildren();wall.hidden=cityInside!=='legacyRoom';if(wall.hidden)return;const items=county.legacyItems(state).filter(item=>state.cityCounty.displays[item.id]).slice(0,8);items.forEach((item,i)=>{const b=document.createElement('button');b.className='county-memory-frame';b.style.left=(15+(i%4)*23)+'%';b.style.top=(29+Math.floor(i/4)*26)+'%';b.dataset.display=item.id;const allowed=['county-camp','county-market','county-garden'];if(item.image&&allowed.includes(item.image)){const img=document.createElement('img');img.src='assets/interiors/'+item.image+'.jpg';img.alt=item.title;b.append(img)}const caption=document.createElement('span');caption.textContent=item.title;b.append(caption);b.onclick=e=>{e.stopPropagation();modal(item.title,'<p class="life-dialogue">'+lifeEsc(item.text)+'</p>');if(item.image&&allowed.includes(item.image)){$('modal').insertAdjacentHTML('beforeend','<img class="life-story-photo" src="assets/interiors/'+item.image+'.jpg" alt="'+lifeEsc(item.title)+'">')}action('Arrange my displays',countyLegacy)};b.addEventListener('pointerdown',e=>e.stopPropagation());wall.append(b)})}
